#pragma once
// One-use bit correlations. All preparation is executed and charged in the
// current nonlinear call. No persistent secret cache or trusted dealer.
#include "resnet50/core/types.hpp"
#include <cstddef>
namespace aqcf2 {
struct RandomBitOT {
    // Server owns k0/k1; client owns t/kt. Unowned fields stay zero.
    std::vector<std::uint8_t> k0,k1,t,kt;
    explicit RandomBitOT(std::size_t n=0):k0(n),k1(n),t(n),kt(n){}
};
// Standard Beaver control, generated by the SAME original SCI AND backend.
// It is a mature control, not part of the claimed cofactor specialization.
template<class B> class PreparedAnd {
    B& s_; Bits a_,b_,c_; std::size_t at_=0;
public:
    PreparedAnd(B& s,std::size_t n):s_(s),a_(n),b_(n),c_(n){
        if(!n)return;
        auto random=s_.random_small(n);
        for(std::size_t i=0;i<n;++i){a_.v[i]=random[i]&1;b_.v[i]=(random[i]>>1)&1;}
        c_=s_.and_(a_,b_); // The complete triple generation cost remains online.
    }
    Bits apply(const Bits& x,const Bits& y){
        x.check();y.check();const auto n=x.v.size();
        require(n==y.v.size()&&at_<=a_.v.size()&&n<=a_.v.size()-at_,"fresh AND triple capacity");
        std::vector<std::uint8_t> own(2*n),peer;
        for(std::size_t i=0;i<n;++i){own[2*i]=x.v[i]^a_.v[at_+i];own[2*i+1]=y.v[i]^b_.v[at_+i];}
        // Only independent one-time-padded differences are reconstructed.
        if(s_.party==1){s_.transfer_masked_bits(1,own);peer=s_.transfer_masked_bits(2,std::vector<std::uint8_t>(2*n));}
        else{peer=s_.transfer_masked_bits(1,std::vector<std::uint8_t>(2*n));s_.transfer_masked_bits(2,own);}
        Bits out(n);
        for(std::size_t i=0;i<n;++i){auto e=own[2*i]^peer[2*i],d=own[2*i+1]^peer[2*i+1];
            out.v[i]=c_.v[at_+i]^(e&b_.v[at_+i])^(d&a_.v[at_+i])^((s_.party==1)?(e&d):0);
            a_.v[at_+i]=b_.v[at_+i]=c_.v[at_+i]=0;
        }
        at_+=n;return out;
    }
    void finish()const{require(at_==a_.v.size(),"all prepared AND triples consumed exactly once");}
};
} // namespace aqcf2
